        "code": "#!/usr/bin/env python3\n\"\"\"Recover the related RSA plaintext from chall.txt using PARI via Sage.\"\"\"\n\nfrom pathlib import Path\nimport re\n\nfrom Crypto.Util.number import long_to_bytes\nfrom sage.all import pari\n\n\ndef main() -> None:\n    values = list(map(int, re.findall(r\"\\d+\", Path(__file__).with_name(\"chall.txt\").read_text())))\n    if len(values) != 5:\n        raise ValueError(f\"Expected N, e, d, c1, c2; found {len(values)} integers\")\n\n    n, e, offset, c1, c2 = values\n\n    # Both ciphertext polynomials have the plaintext m as a common root.\n    # Keep offset in Z/nZ before exponentiation so PARI reduces every\n    # polynomial coefficient modulo n during expansion.\n    expr = (\n        f\"gcd(x^{e} - Mod({c1},{n}), \"\n        f\"(x + Mod({offset},{n}))^{e} - Mod({c2},{n}))\"\n    )\n    common = pari(expr)\n\n    if int(pari(f\"poldegree({common})\")) != 1:\n        raise ValueError(f\"Expected a linear gcd, got: {common}\")\n\n    a = int(pari(f\"lift(polcoeff({common},1))\"))\n    b = int(pari(f\"lift(polcoeff({common},0))\"))\n    message = (-b * pow(a, -1, n)) % n\n    plaintext = long_to_bytes(message)\n\n    # Verify against both values printed by the challenge.\n    assert pow(message, e, n) == c1\n    assert pow(message + offset, e, n) == c2\n    assert plaintext.startswith(b\"hiCTF{\") and plaintext.endswith(b\"}\")\n\n    print(f\"<FLAG>{plaintext.decode()}</FLAG>\")\n\n\nif __name__ == \"__main__\":\n    main()"
