      {
        "title": "Automated Solver Script (solve.py)",
        "content": "Implementasi solver mandiri untuk menyelesaikan challenge secara deterministik. Jalankan dengan `python3 solve.py`.",
        "code": "#!/usr/bin/env python3\n\"\"\"Restore the Cold Chain CTF controller and wait for its compliance proof.\"\"\"\n\nimport argparse\nimport socket\nimport ssl\nimport sys\nimport time\n\nfrom coldlink_tech import auth_token\n\n\nDEFAULT_HOST = \"cold-chain-control-bedcb4edbdf5.chall.hiddeninvestigations.net\"\nDEFAULT_PORT = 1337\n\n\nclass Controller:\n    def __init__(self, host, port):\n        raw = socket.create_connection((host, port), timeout=10)\n        context = ssl.create_default_context()\n        self.sock = context.wrap_socket(raw, server_hostname=host)\n        self.file = self.sock.makefile(\"rwb\", buffering=0)\n        self.serial = None\n        self.nonce = None\n        self._greet()\n\n    def _line(self):\n        data = self.file.readline()\n        if not data:\n            raise ConnectionError(\"controller closed the connection\")\n        return data.decode(\"utf-8\", \"replace\").rstrip(\"\\r\\n\")\n\n    def _response(self):\n        lines = []\n        while True:\n            line = self._line()\n            lines.append(line)\n            if line.startswith((\"OK\", \"ERR\")):\n                return lines\n\n    def _greet(self):\n        while True:\n            line = self._line()\n            if line.startswith(\"SERIAL \"):\n                self.serial = line.split(None, 1)[1].strip()\n            elif line.startswith(\"NONCE \"):\n                self.nonce = line.split(None, 1)[1].strip()\n            if line.startswith((\"OK\", \"ERR\")):\n                break\n        if not self.serial or not self.nonce:\n            raise RuntimeError(\"controller greeting did not include SERIAL and NONCE\")\n\n    def send(self, command):\n        self.file.write((command + \"\\n\").encode())\n        response = self._response()\n        if response[-1].startswith(\"ERR\"):\n            raise RuntimeError(\"%s: %s\" % (command, response[-1]))\n        return response\n\n    def authenticate(self):\n        token = auth_token(self.serial, self.nonce)\n        response = self.send(\"AUTH %s %s\" % (self.serial, token))\n        if not response[-1].startswith(\"OK role=technician\"):\n            raise RuntimeError(\"technician authentication failed\")\n\n    def close(self):\n        try:\n            self.send(\"QUIT\")\n        except (ConnectionError, OSError, RuntimeError):\n            pass\n        self.file.close()\n        self.sock.close()\n\n\ndef fields(data_line):\n    return dict(part.split(\"=\", 1) for part in data_line.split()[1:] if \"=\" in part)\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\"--host\", default=DEFAULT_HOST)\n    parser.add_argument(\"--port\", type=int, default=DEFAULT_PORT)\n    parser.add_argument(\"--timeout\", type=int, default=180,\n                        help=\"maximum seconds to wait for compliance (default: 180)\")\n    args = parser.parse_args()\n\n    controller = Controller(args.host, args.port)\n    try:\n        controller.authenticate()\n        print(\"Authenticated as technician: %s\" % controller.serial)\n\n        schedules = [line for line in controller.send(\"SCHED LIST\")\n                     if line.startswith(\"DATA \")]\n        macros = [line for line in controller.send(\"MACRO LIST\")\n                  if line.startswith(\"DATA \")]\n        active_forcing = [fields(line) for line in schedules\n                          if fields(line).get(\"enabled\") == \"1\"\n                          and fields(line).get(\"action\") == \"force_defrost\"]\n        if [entry.get(\"sched\") for entry in active_forcing] != [\"S9\"]:\n            raise RuntimeError(\"expected S9 to be the only enabled force_defrost schedule\")\n\n        s9_lines = controller.send(\"SCHED GET S9\")\n        m2_lines = controller.send(\"MACRO GET M2\")\n        s9 = next(fields(line) for line in s9_lines if line.startswith(\"DATA \"))\n        m2 = next(fields(line) for line in m2_lines if line.startswith(\"DATA \"))\n        if s9.get(\"sched\") != \"S9\" or m2.get(\"macro\") != \"M2\":\n            raise RuntimeError(\"expected schedule S9 and maintenance macro M2\")\n        if m2.get(\"action\") != \"ensure_schedule\" or m2.get(\"target\") != \"S9\":\n            raise RuntimeError(\"M2 does not match the observed schedule re-enable fault\")\n        if not any(fields(line).get(\"macro\") == \"M2\" for line in macros):\n            raise RuntimeError(\"M2 was not present in MACRO LIST\")\n\n        # Stop the background re-enable action before disabling its target.\n        for command in (\"MACRO DISABLE M2\", \"SCHED SET S9 action=noop enabled=0\"):\n            print(\"%s -> %s\" % (command, controller.send(command)[-1]))\n\n        for line in controller.send(\"CASES\"):\n            if line.startswith(\"DATA \"):\n                print(line)\n\n        deadline = time.monotonic() + args.timeout\n        while time.monotonic() < deadline:\n            status = [line for line in controller.send(\"STATUS\")\n                      if line.startswith(\"DATA \")]\n            for line in status:\n                print(line)\n            flag_lines = [line for line in status if \"flag=\" in line]\n            if flag_lines:\n                return\n            time.sleep(1)\n        raise TimeoutError(\"compliance proof did not appear within %d seconds\" % args.timeout)\n    finally:\n        controller.close()\n\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except (ConnectionError, OSError, RuntimeError, TimeoutError) as exc:\n        print(\"error: %s\" % exc, file=sys.stderr)\n        raise SystemExit(1)"
      }
