        "title": "Automated Solver Script (solve.py)",
        "content": "Implementasi solver mandiri untuk menyelesaikan challenge secara deterministik. Jalankan dengan `python3 solve.py`.",
        "code": "#!/usr/bin/env python3\n\"\"\"Build the accepted calibration vector and ask the local validator for its config.\"\"\"\n\nfrom pathlib import Path\nimport struct\nimport subprocess\nimport sys\n\n\ndef main() -> None:\n    # The validator expects four little-endian IEEE-754 doubles as 64 hex chars.\n    # Keep the third value as the actual rounded sum checked by the binary.\n    vector = struct.pack(\"<dddd\", 1.1, 2.2, 1.1 + 2.2, -0.0).hex()\n    binary = Path(__file__).with_name(\"epsilon-drift\")\n    print(f\"calibration vector: {vector}\", file=sys.stderr)\n    subprocess.run([str(binary), vector], check=True)\n\n\nif __name__ == \"__main__\":\n    main()"
