        "code": "#!/usr/bin/env python3\n\"\"\"Recover the accepted Signal Lock token and decrypt the embedded flag.\"\"\"\n\nimport hashlib\n\n\nMASK64 = (1 << 64) - 1\nTRANSFORM_TARGET = 0xAFE7C5708F40EBC4\nXOR_CONST = 0xA5A5A5A55A5A5A5A\nMULTIPLIER = 0x9E3779B97F4A7C15\nADD_CONST = 0x0123456789ABCDEF\nROTATION = 29\n\n# Literal returned by signal_lock:cipher/0 in the BEAM module.\nCIPHER = bytes.fromhex(\n    \"f3a78b575b93c60be646d9eefd1f0aa0\"\n    \"ac5ac53a2b0107f1a5c84adf4d989dc0\"\n    \"6c09680db73f54ad89bdd8ae0530c27b\"\n)\n\n\ndef transform(value: int) -> int:\n    \"\"\"Mirror signal_lock:transform/1 using unsigned 64-bit arithmetic.\"\"\"\n    value = ((value ^ XOR_CONST) * MULTIPLIER) & MASK64\n    value = ((value << ROTATION) | (value >> (64 - ROTATION))) & MASK64\n    return (value + ADD_CONST) & MASK64\n\n\ndef recover_token() -> int:\n    # Undo the final addition and rotation, then multiply by the modular\n    # inverse of the odd multiplier. The BEAM bit-syntax match reads 8 bytes\n    # as one big-endian 64-bit integer.\n    value = (TRANSFORM_TARGET - ADD_CONST) & MASK64\n    value = ((value >> ROTATION) | (value << (64 - ROTATION))) & MASK64\n    value = (value * pow(MULTIPLIER, -1, 1 << 64)) & MASK64\n    value ^= XOR_CONST\n    assert transform(value) == TRANSFORM_TARGET\n    return value\n\n\ndef decrypt(seed: int) -> bytes:\n    # keystream/4 hashes <<seed:64, counter:32>> repeatedly and concatenates\n    # each SHA-256 digest until it can cover the 48-byte ciphertext.\n    stream = bytearray()\n    counter = 0\n    while len(stream) < len(CIPHER):\n        block_input = seed.to_bytes(8, \"big\") + counter.to_bytes(4, \"big\")\n        stream.extend(hashlib.sha256(block_input).digest())\n        counter += 1\n    return bytes(cipher_byte ^ key_byte\n                 for cipher_byte, key_byte in zip(CIPHER, stream))\n\n\ndef main() -> None:\n    token_value = recover_token()\n    token = token_value.to_bytes(8, \"big\")\n    flag = decrypt(token_value)\n    print(f\"token: {token.decode('ascii')}\")\n    print(f\"flag: {flag.decode('ascii')}\")\n\n\nif __name__ == \"__main__\":\n    main()"
